  /// Reference to the original comment {@link discussionboard_comments.id}. Links edit to its base comment. Maintains 3NF: no duplication of comment content or thread.
  comment_id String @db.Uuid

  /// Reference for editor of the comment (member or moderator) {@link discussionboard_members.id}. Ensures traceability. Not nullable.
  editor_id String @db.Uuid

  /// Short summary explaining reason for edit - Implements requirement for moderator review. 3NF compliant. Nullable if not specified by user/editor.
  edit_summary String?

  /// Comment contents after edit - Captures full content for audit and rollback. Not nullable; ensures traceability, versioning, and full history without denormalized data.
  body_after_edit String

  /// Edit creation timestamp. Implements edit order, audit trail, and moderation workflows.
